grid=[row+[8]*(25-len(row)) for row in grid]; H,W=25,25; seen=set(); comps=[]
for r in range(H):
 for c in range(W):
  v=grid[r][c]
  if v==8 or (r,c) in seen: continue
  q=[(r,c)]; seen.add((r,c)); comp=[]
  while q:
   y,x=q.pop(); comp.append((y,x))
   for dy in (-1,0,1):
    for dx in (-1,0,1):
     p=(y+dy,x+dx)
     if 0<=p[0]<H and 0<=p[1]<W and p not in seen and grid[p[0]][p[1]]==v:
      seen.add(p);q.append(p)
  comps.append((v,comp))
[(v,len(p),min(y for y,x in p),max(y for y,x in p),min(x for y,x in p),max(x for y,x in p)) for v,p in comps]

out=[[8]*W for _ in range(H)]
for v,p in comps:
 top=min(y for y,x in p); bot=max(y for y,x in p)
 dy=(H-1-bot) if (top+bot)/2 < (H-1)/2 else -top
 # objects centered above vertical middle move bottom; below move top
 for y,x in p:
  yy=y+dy
  if out[yy][x]!=8: print('collision',v,yy,x)
  out[yy][x]=v
print('\n'.join(' '.join(map(str,row)) for row in out))
